/**
 * The remote MCP servers the agent can discover, as plain data.
 *
 * A 1:1 copy of the host catalog in src/shared/lib/mcp/common-servers.ts. It is a
 * copy rather than an import because the container builds with plain `tsc` and
 * cannot reach @shared; src/shared/lib/mcp/agent-catalog-parity.test.ts asserts
 * the two stay identical. Kept free of imports so that test can read it without
 * pulling in the agent SDK.
 *
 * Generated — - regenerate rather than hand-editing, then let the parity test check it.
 */

export interface McpServiceInfo {
  slug: string
  displayName: string
  description: string
  url: string
  authType: 'none' | 'oauth' | 'bearer'
  category: string
  /**
   * The server rejects dynamic client registration, so the user must register an
   * OAuth app in the provider's console and allowlist our callback before this
   * can connect. Surfaced to the model so it can warn the user up front rather
   * than letting them discover it inside the approval prompt.
   *
   * Mirrors `setup.requiresClientId` on the host catalog entry.
   */
  requiresOwnOAuthApp?: boolean
}

